/**
 * R3R *Vehicle Design* — the Chassis Table and the Power Plant Table, as numbers. TODO 287, slice 1. Pure data.
 *
 * Transcribed by eye from rendered pages of Rigger 3 Revised (printed pp.194-205; PDF page = printed + 2): the tables are
 * images whose text layer is unreadable, so `pdftotext` cannot check them. `tests/vehicle-design-tables.test.mjs`
 * spot-checks rows against the book's own worked examples (pp.109-114).
 *
 * Cells are as printed. A plain figure is a number; anything else stays the printed string and is read by
 * `VehicleDesign.cell` (scripts/data/vehicle-design.mjs):
 *   - `B` is the vehicle's Body: '5xB', '50-(5xB)', '10+(20xB)', '1.2÷B'.
 *   - Aircraft Speed pairs 'stall/Speed' ('20/60'): R3R p.116 — design options never change the stall speed.
 *   - Submarine pairs 'surface/submerged' ('30/25'); ships' 'N (M)' and Signature 'N/M' (normal/sonar) keep
 *     the first figure as the rating and the rest for the GM.
 *   - Body / Armor with 'H' / 'B' are Hull and Barrier-armour ratings (ships, subs).
 *   - '—' (null here) is "none".
 * Nothing here is rulebook prose: names, numbers and short feature tags only.
 */

/** Chassis categories in the table's order; `skill` is the Vehicle skill family the chassis falls under (p.104). */
export const CATEGORIES = {
  bike: 'Bike', boat: 'Boat', car: 'Car', fixedwing: 'Fixed-Wing Aircraft', hover: 'Hovercraft', rotor: 'Rotor Craft',
  ship: 'Ship', sub: 'Submarine', vectored: 'Vectored-Thrust Aircraft', special: 'Special Vehicle',
};

/** Power plants (p.109-111); `fuel` is the unit its Fuel and Economy are printed in. */
export const PLANTS = {
  R:   { name: 'Chemical Rocket',     fuel: 'PF' },
  D:   { name: 'Diesel',              fuel: 'liters' },
  E:   { name: 'Electric Battery',    fuel: 'PF' },
  EC:  { name: 'Electric Fuel Cell',  fuel: 'PF' },
  G:   { name: 'Gasoline',            fuel: 'liters' },
  J:   { name: 'Jet Propeller',       fuel: 'liters' },
  JET: { name: 'Jet Turbine',         fuel: 'liters' },
  M:   { name: 'Methane',             fuel: 'bars' },
  N:   { name: 'Nuclear',             fuel: null },
  S:   { name: 'Sail',                fuel: null },
};

const _ = null;   // the table's "—"

/* Chassis rows: id, name, Body, start CF, max CF, Handling, Armor, Autonav/Pilot, Sensor/Sonar, Seating, Entry Points,
 * Design Points, Mark-Up Factor, other features (short tag), extra (submarines: start/max Depth). */
const C = (id, name, body, cf, maxCf, handling, armor, autonav, sensor, seating, entry, dp, markUp, features = '', extra = {}) =>
  ({ id, name, body, cf, maxCf, handling, armor, autonav, sensor, seating, entry, dp, markUp, features, ...extra });

const group = (category, page, drone, rows) => rows.map(r => ({ ...r, category, page, drone }));

