/* Rows: label as printed, the chassis it serves, Load start/max, Speed start/max, Accel start/max, Signature, starting
 * Fuel, Economy start/max, Design Points, People Space (in Load). */
const P = (label, chassis, load, loadMax, speed, speedMax, accel, accelMax, sig, fuel, econ, econMax, dp, people = null) =>
  ({ label, chassis: [].concat(chassis), load, loadMax, speed, speedMax, accel, accelMax, sig, fuel, econ, econMax, dp, people });

